//! 🧪️ Original causal identities remain hidden until commit and return exactly through aborted suffixes.
use super::*;
fn fund(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn observed<T>(run:impl FnOnce()->(T,RetainedCloneProgress))->T{let((result,p),born,released)=semio_framework_trace_memory_testing::observe_backing(run);assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));result}
fn retire(text:String){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(text).map_err(|(e,_)|e).unwrap();while !owner.terminal_is_empty(){let d=owner.next_demand(4096).unwrap();observed(||{let step=owner.step(fund(d)).unwrap();((),step.progress())});}}
fn close(dag:&mut MutationDag){while let Some(owner)=dag.take_one_close_owner(){match owner{MutationDagCloseOwner::Identity(text)=>retire(text),MutationDagCloseOwner::Envelope(_)=>panic!("fixture has original identity rows")}}while !dag.backing_is_empty(){let release=dag.next_backing_release_byte_demand();let((_,bytes,_),born,released)=semio_framework_trace_memory_testing::observe_backing(||dag.close_backing_step(1,release));assert_eq!((born,released),(0,bytes));}}
#[test]
fn original_causal_seed_suffix_commits_once_and_aborts_every_unpublished_prefix(){
 let f:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for cut in std::iter::once(None).chain(f["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut dag=MutationDag::new();for id in f["existing"].as_array().unwrap(){dag.seed_applied(semio_framework_replication_ids::MutationId(id.as_str().unwrap().into())).unwrap();}let d=MutationDag::original_seed_birth_demands();let mut owner=Some(observed(||dag.admit_original_seeds(fund(d)).unwrap().unwrap()));let mut foreign=MutationDag::new();assert!(foreign.commit_original_seeds(&mut owner,fund(MutationDag::original_seed_commit_demands())).is_err());assert!(owner.is_some());assert!(observed(||(foreign.can_commit_original_seeds(owner.as_ref().unwrap(),fund(MutationDag::original_seed_commit_demands())),Default::default())).is_err());close(&mut foreign);
  for(index,id)in f["staged"].as_array().unwrap().iter().enumerate(){if cut.is_some_and(|cut|index>=cut){break}let mut identity=Some(semio_framework_replication_ids::MutationId(id.as_str().unwrap().into()));for turn in 0..100000{if identity.is_none(){break}let d=MutationDag::original_seed_append_demands();assert!(d.copy_bytes<=f["quantum"].as_u64().unwrap()as usize);for axis in 0..5{let mut g=fund(d);let limit=match axis{0=>&mut g.maximum_items,1=>&mut g.maximum_copy_bytes,2=>&mut g.maximum_capacity_bytes,3=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *limit==0{continue}*limit-=1;let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||dag.stage_original_seed(owner.as_ref().unwrap(),&mut identity,g).unwrap());assert!(result.is_none());assert_eq!((born,released),(0,0));assert!(identity.is_some());}observed(||((),dag.stage_original_seed(owner.as_ref().unwrap(),&mut identity,fund(d)).unwrap().unwrap()));if dag.original_seed_stage.as_ref().unwrap().candidate.is_some(){assert!(observed(||(dag.can_commit_original_seeds(owner.as_ref().unwrap(),fund(MutationDag::original_seed_commit_demands())),Default::default())).is_err());}assert!(turn<99999);}for value in f["staged"].as_array().unwrap(){assert!(!dag.original_seed_is_applied(value.as_str().unwrap()));}assert!(dag.original_seed_is_applied(f["existing"][0].as_str().unwrap()));}
  if cut.is_none(){let d=MutationDag::original_seed_commit_demands();for axis in [0,1,4]{let mut denied=fund(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,_=>denied.maximum_depth=0};assert!(!observed(||(dag.can_commit_original_seeds(owner.as_ref().unwrap(),denied).unwrap(),Default::default())));assert!(owner.is_some());}assert!(observed(||(dag.can_commit_original_seeds(owner.as_ref().unwrap(),fund(d)).unwrap(),Default::default())));observed(||((),dag.commit_original_seeds(&mut owner,fund(d)).unwrap().unwrap()));assert!(owner.is_none());for id in f["staged"].as_array().unwrap(){assert!(dag.original_seed_is_applied(id.as_str().unwrap()));}}
  else{while let Some(token)=owner.as_ref(){let d=dag.original_seed_abort_demands(token).unwrap();let identity=observed(||dag.abort_original_seed_step(&mut owner,fund(d)).unwrap().unwrap());if let Some(identity)=identity{retire(identity)}}for id in f["staged"].as_array().unwrap(){assert!(!dag.original_seed_is_applied(id.as_str().unwrap()));}}
  close(&mut dag);
 }
}
